import {reportRange,aggregateDemand} from './reports-domain.js';
export function setupReports(context){const $=id=>document.getElementById(id);let owner=null,generation=0,cache=null,busy=false;
 const localDate=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const today=new Date(),start=new Date();start.setDate(start.getDate()-6);$('reports-from').value=localDate(start);$('reports-to').value=localDate(today);
 const node=(tag,text,css)=>{const n=document.createElement(tag);n.textContent=text;if(css)n.className=css;return n;};
 function render(result){$('reports-summary').replaceChildren();for(const [label,value] of [['Listas',result.listCount],['Itens solicitados',result.itemCount],['Produtos / embalagens',(result.productCount??result.products.length)]]){const card=node('div','','report-stat');card.append(node('strong',value),node('span',label));$('reports-summary').append(card);}
 const root=$('reports-results');root.replaceChildren();if(!result.products.length){root.append(node('p','Nenhuma solicitação encontrada neste período.'));return;}root.append(node('p','Ranking por presença em listas distintas. Exibindo '+Math.min(50,result.products.length)+' de '+(result.productCount??result.products.length)+' produtos/embalagens.','muted small'));
 const table=document.createElement('table');table.className='report-table';const caption=node('caption','Produtos mais solicitados — frequência por lista');table.append(caption);const head=document.createElement('thead'),hr=document.createElement('tr');for(const text of ['Produto','Listas','Quantidade solicitada'])hr.append(node('th',text));head.append(hr);table.append(head);const body=document.createElement('tbody');result.products.slice(0,50).forEach((p,index)=>{const tr=document.createElement('tr'),description=document.createElement('td');description.append(node('strong',(index+1)+'. '+p.name),node('small','Código '+p.code,'muted'));tr.append(description,node('td',p.lists),node('td',p.quantity.toLocaleString('pt-BR')+' '+p.unit.toUpperCase()));body.append(tr);});table.append(body);const wrap=node('div','','report-table-wrap');wrap.append(table);root.append(wrap);}
 $('reports-form').onsubmit=async event=>{event.preventDefault();const {client,session,profile}=context();if(busy||!session||!profile?.active)return;const run=++generation;busy=true;$('reports-run').disabled=true;$('reports-results').replaceChildren();$('reports-summary').replaceChildren();
 try{const range=reportRange($('reports-from').value,$('reports-to').value),requester=$('reports-requester').value.trim(),status=$('reports-status').value,team=['admin','estoquista'].includes(profile.role);const key=JSON.stringify([session.user.id,team,range,requester,status]);if(cache?.key===key&&Date.now()-cache.time<300000){render(cache.result);$('reports-message').textContent='Resultado já consultado nesta sessão · '+new Date(cache.time).toLocaleTimeString('pt-BR');return;}
 $('reports-message').textContent='Consultando solicitações do período…';let {data:result,error}=await client.rpc('restock_report',{date_from:$('reports-from').value,date_to:$('reports-to').value,requester,state:status});
 if(run!==generation)return;
 let legacy=false;
 if(error?.code==='PGRST202'){
 legacy=true;const rows=[];
 for(let offset=0;offset<=5000;offset+=500){if(run!==generation)return;let q=client.from('restock_requests').select('product_code,product_name,unit,quantity,list_id,lists:restock_lists!inner(created_at,created_by,requester_name,status)').gte('lists.created_at',range.from).lt('lists.created_at',range.until);if(!team)q=q.eq('lists.created_by',session.user.id);if(requester)q=q.ilike('lists.requester_name','%'+requester.replace(/[%_]/g,'')+'%');if(status!=='all')q=q.eq('lists.status',status);const response=await q.order('id',{ascending:true}).range(offset,Math.min(offset+499,5000));if(response.error)throw new Error('Não foi possível consultar o relatório.');rows.push(...response.data);if(rows.length>5000)throw new Error('Reduza o período: mais de 5.000 itens.');if(response.data.length<500)break;}
 result=aggregateDemand(rows);error=null;
 }
 if(error)throw new Error('Não foi possível consultar o relatório. Tente novamente.');
 if(run!==generation)return;
 cache=legacy?null:{key,result,time:Date.now()};render(result);$('reports-message').textContent='Relatório gerado em '+new Date().toLocaleString('pt-BR')+'. Quantidades solicitadas, não saldo disponível.'+(legacy?' Resumos históricos ainda não ativados: execute a migração 014 no Supabase.':' Inclui resumos históricos preservados.');
 }catch(error){if(run===generation)$('reports-message').textContent=error.message;}finally{if(run===generation){busy=false;$('reports-run').disabled=false;}}};
 return {configure(profile,id){const next=id+':'+profile?.role+':'+profile?.active;if(next!==owner){owner=next;generation++;busy=false;cache=null;$('reports-run').disabled=false;$('reports-results').replaceChildren();$('reports-summary').replaceChildren();$('reports-message').textContent='Escolha o período e clique em Gerar relatório.';}$('reports-scope').textContent=['admin','estoquista'].includes(profile?.role)?'Visão da equipe: todas as solicitações acessíveis ao seu perfil.':'Seu histórico: apenas as listas enviadas por você.';}};
}
